const now=()=>Math.floor(Date.now()/1000),day=()=>new Date(Date.now()+3*3600e3).toISOString().slice(0,10),week=()=>Math.floor((Date.now()/1000+3*3600-4*86400)/604800);
let IDX=null,IDX_T=0,TOK=null;
let ENVG=null;async function index(){if(IDX&&Date.now()-IDX_T<600000)return IDX;const r=await fetch(SITE+'/data/index.json',{cf:{cacheTtl:300}});const a=await r.json();const M=new Map(a.map(x=>[x[0].toLowerCase(),x]));if(ENVG)try{await ENVG.DB.prepare('CREATE TABLE IF NOT EXISTS res(nick TEXT PRIMARY KEY,num INTEGER,ts INTEGER)').run();for(const q of (await ENVG.DB.prepare('SELECT nick,num FROM res').all()).results)if(!M.has(q.nick))M.set(q.nick,[q.nick,q.num,['новый житель']])}catch(e){}IDX=M;IDX_T=Date.now();return IDX}
async function addRes(env,n){await env.DB.prepare('CREATE TABLE IF NOT EXISTS res(nick TEXT PRIMARY KEY,num INTEGER,ts INTEGER)').run();const c=await env.DB.prepare('SELECT COUNT(*) c FROM res').first();const idx=await index();const num=idx.size+1;await env.DB.prepare('INSERT OR IGNORE INTO res(nick,num,ts) VALUES(?,?,?)').bind(n,num,now()).run();const x=[n,num,['новый житель']];idx.set(n,x);return x}
let SQ=null,SQI=null;function sq(n){return n.replace(/[._\s]+/g,'')}
async function findNick(n){const idx=await index();let x=idx.get(n);if(x)return {x};if(SQI!==idx){SQ=new Map();for(const [k,v] of idx){const q=sq(k);SQ.set(q,(SQ.get(q)||[]).concat([v]))}SQI=idx}const m=SQ.get(sq(n))||[];if(m.length===1)return {x:m[0]};return {many:m}}
function norm(t){t=(t||'').trim().toLowerCase();const m=t.match(/instagram\.com\/([a-z0-9._]+)/);if(m)t=m[1];return t.replace(/^@+/,'').replace(/[\s/]+$/,'').replace(/\s+/g,'')}
async function kv(env,k,v){if(v===undefined){const r=await env.DB.prepare('SELECT v FROM kv WHERE k=?').bind(k).first();return r&&r.v}await env.DB.prepare('INSERT OR REPLACE INTO kv(k,v) VALUES(?,?)').bind(k,String(v)).run()}
async function token(env){if(!TOK)TOK=await kv(env,'token');return TOK}
async function tg(env,m,b){const t=await token(env);return fetch('https://api.telegram.org/bot'+t+'/'+m,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)}).then(r=>r.json())}

