function wq(p){const s=stat(p),w=week();if(!s.wq||s.wq.w!==w){let h=0;for(const c of 'w'+w+p.tg)h=(h*31+c.charCodeAt(0))>>>0;const ids=[];let k=h;while(ids.length<3){const i=k%WQ.length;if(!ids.includes(i))ids.push(i);k=Math.floor(k/5)+7}s.wq={w,ids,p:{},c:[]};p.st=JSON.stringify(s)}return s.wq}
function mis(p){const d=day();let m=p.mis?JSON.parse(p.mis):null;if(!m||m.d!==d){let h=0;for(const c of d+p.tg)h=(h*31+c.charCodeAt(0))>>>0;const ids=[];let k=h;while(ids.length<6){const i=k%MIS.length;if(!ids.includes(i))ids.push(i);k=Math.floor(k/7)+13}m={d,ids,p:{},c:[]};p.mis=JSON.stringify(m)}return m}
function bump(p,kind,n=1,max=false){{const q=wq(p),s=stat(p);for(const i of q.ids)if(WQ[i][0]===kind&&!max)q.p[kind]=(q.p[kind]||0)+n;s.wq=q;p.st=JSON.stringify(s)}const m=mis(p);for(const i of m.ids){const M=MIS[i];if(M[0]===kind){const v=m.p[kind]||0;m.p[kind]=max?Math.max(v,n):v+n}}p.mis=JSON.stringify(m)}
