async function cwInit(env){if(globalThis.__cwi)return;await env.DB.prepare('CREATE TABLE IF NOT EXISTS cw(wk INTEGER,cid INTEGER,pts INTEGER,PRIMARY KEY(wk,cid))').run();await env.DB.prepare('CREATE TABLE IF NOT EXISTS cwm(wk INTEGER,nick TEXT,cid INTEGER,pts INTEGER,PRIMARY KEY(wk,nick))').run();await env.DB.prepare('CREATE TABLE IF NOT EXISTS cwr(nick TEXT PRIMARY KEY,c INTEGER,ttl TEXT,wk INTEGER,pl INTEGER)').run();globalThis.__cwi=1}
async function cwAdd(env,p,n){try{if(!n)return;await cwInit(env);const m=await env.DB.prepare('SELECT cid FROM clm WHERE nick=?').bind(p.nick).first();if(!m)return;const w=week();await env.DB.prepare('INSERT INTO cw(wk,cid,pts) VALUES(?,?,?) ON CONFLICT(wk,cid) DO UPDATE SET pts=pts+excluded.pts').bind(w,m.cid,n).run();await env.DB.prepare('INSERT INTO cwm(wk,nick,cid,pts) VALUES(?,?,?,?) ON CONFLICT(wk,nick) DO UPDATE SET pts=pts+excluded.pts,cid=excluded.cid').bind(w,p.nick,m.cid,n).run()}catch(e){}}
const CWR=[5000,3000,1500];
async function cwPay(env){try{await cwInit(env);const pw=week()-1;if(await kv(env,'cwpaid:'+pw))return;const r=await env.DB.prepare('INSERT OR IGNORE INTO kv(k,v) VALUES(?,?)').bind('cwpaid:'+pw,'1').run();if(!r.meta||!r.meta.changes)return;const top=(await env.DB.prepare('SELECT cid,pts FROM cw WHERE wk=? ORDER BY pts DESC LIMIT 3').bind(pw).all()).results;
 for(let i=0;i<top.length;i++){const ms=(await env.DB.prepare('SELECT nick FROM cwm WHERE wk=? AND cid=? AND pts>=10').bind(pw,top[i].cid).all()).results;for(const x of ms)await env.DB.prepare('INSERT INTO cwr(nick,c,ttl,wk,pl) VALUES(?,?,?,?,?) ON CONFLICT(nick) DO UPDATE SET c=c+excluded.c,ttl=CASE WHEN excluded.ttl<>\'\' THEN excluded.ttl ELSE ttl END,wk=excluded.wk,pl=excluded.pl').bind(x.nick,CWR[i],i===0?'cwin':'',pw,i+1).run()}
 if(top[0]){const c=await env.DB.prepare('SELECT name,emo FROM clan WHERE id=?').bind(top[0].cid).first();if(c){await kv(env,'cwlast',JSON.stringify({name:c.name,emo:c.emo,pts:top[0].pts,wk:pw}));await feed(env,'⚔️ Битву кланов недели выиграл клан '+c.emo+' «'+c.name+'» — '+top[0].pts.toLocaleString('ru')+' очков!')}}}catch(e){}}
