function sgAdd(L,k,n){const S=L.sg;if(!S||!S.acc)return;const c=STORY[S.c];if(!c)return;if(c[1]===k||(c[1]==='hunt'&&['rabbit','goat','wolf','lion'].includes(k)))S.p=Math.min(c[2],S.p+n)}
function sgView(L,LO){const S=L.sg||{c:0,p:0,acc:0},c=STORY[S.c];if(!c)return {done:1,c:S.c,of:STORY.length};const loot=c[1]==='skin'||c[1]==='meat';return {c:S.c,of:STORY.length,who:c[0],k:c[1],n:c[2],t:c[3],txt:c[4],r:c[5],acc:c[1]==='talk'?1:S.acc,p:c[1]==='talk'?1:loot?Math.min(c[2],LO[c[1]]||0):S.p}}
function fxAdd(L,k,n){sgAdd(L,k,n);for(const w of ['e','f','g','k','r','l','t']){const q=L.cq&&L.cq[w];if(!q||!q.acc)continue;const c=w==='g'?GNQ[q.i%GNQ.length]:w==='k'?GKQ[q.i%GKQ.length]:w==='r'?RGQ[q.i%RGQ.length]:w==='l'?ELQ[q.i%ELQ.length]:w==='t'?TRQ[q.i%TRQ.length]:w==='f'?FXQ.h[q.i%FXQ.h.length]:FXQ.e[q.i%FXQ.e.length];if(c[0]===k||(c[0]==='hunt'&&['rabbit','goat','wolf','lion'].includes(k)))q.p=Math.min(c[1],q.p+n)}}
function shAdd(L,k,n){const q=L.cq&&L.cq.h;if(!q||!q.acc)return;const c=SHQ[q.i%SHQ.length];if(c[0]===k)q.p=Math.min(c[1],q.p+n)}
function cqAdd(L,k,n){const q=L.cq&&L.cq.s;if(!q||!q.acc)return;const c=SMQ[q.i%SMQ.length];if(c[0]===k)q.p=Math.min(c[1],q.p+n)}
